insert into games (id, data) values ('game-pathbuilder', $j${"id":"game-pathbuilder","title":"Pathbuilder","slug":"pathbuilder","kind":"embed","summary":"A 3D engineering puzzle. Lay road cards one at a time so a little car can cross rivers on bridges and drive all the way home. Play alone or with a friend using a 6-character code.","players":"1, or 2 online (share a code)","minutes":10,"ageMin":6,"ageMax":12,"rules":["Pick a road card, then click a square next to the end of your road. Turn the card with the Turn button or the R key.","Roads only connect edge to edge, so line the openings up. The car drives along the road you build and stops where it ends.","Rivers need a bridge card. A bridge can also sit on grass or go over another road, as long as it crosses the road and does not run along it.","Trees and rocks are in the way, so plan around them. Medium and Hard are bigger islands with more to avoid.","Stuck? Swap one card, press Randomize my deck for a whole new hand, or Undo your last card.","The par is the shortest road possible. Use about that many cards to earn three stars.","Switch between the 3D view and a top-down 2D view, and turn the board a quarter at a time with the arrow buttons or Q and E.","For 2 players, choose 2 players, then make a room and share the 6-character code. Your friend types it under Join a friend. You take turns and the first car home wins.","Pick Set stage for the same island every time, or Random map for a new one."],"leadsTo":"act-marble-run","interactive":true,"path":"games/pathbuilder.html","icon":"house","p1":"#C9E7BC","p2":"#2E6B2B","status":"published","featured":true,"createdAt":"2026-10-28T06:00:00.000Z","updatedAt":"2026-10-28T06:00:00.000Z","badge":"New","order":0,"cover":{"src":"assets/games/pathbuilder.jpg","alt":"A red toy car drives round a bend on a winding road laid across a floating island in a deep blue sea, with more roads, a river, trees and little houses on the islands around it, from the 3D game Pathbuilder"}}$j$::jsonb)
on conflict (id) do update set data = excluded.data, updated_at = now();

insert into portal_entries (id, data) values ('portal-pathbuilder', $j${"id":"portal-pathbuilder","slug":"pathbuilder","title":"Pathbuilder","layout":"game","category":"New games","status":"published","publishedAt":"2026-10-28","description":"A new 3D game for newsletter subscribers. Build a road one card at a time, cross rivers on bridges, and drive the little red car home. Play on your own, or with a friend online.","cover":{"src":"assets/games/pathbuilder.jpg","alt":"A red toy car drives round a bend on a winding road laid across a floating island in a deep blue sea, with more roads, a river, trees and little houses on the islands around it, from the 3D game Pathbuilder"},"coverStill":"","gameId":"game-pathbuilder","gamePath":"games/pathbuilder.html","gameMode":"launch","gameLabel":"Play Pathbuilder","privateGameId":"","privateGameKb":0,"bookId":"","bookMode":"launch","bookPath":"","videoUrl":"","gallery":[],"howToPlay":["Pick a road card, then click a square next to the end of your road. Press R, or the Turn button, to rotate the card.","Line up the openings. Roads only connect edge to edge, and the car drives along the road you build.","Rivers need a bridge card. A bridge can also go over another road, as long as it crosses the road instead of running along it.","Stuck? Swap one card, press Randomize my deck for a whole new hand, or Undo your last card.","Choose 1 player or 2 players. To play a friend, make a room, share the 6-character code, and take turns. The first car home wins!","Pick Easy, Medium or Hard, and switch between the 3D view and the top-down 2D view."],"vocabWord":"engineer","vocabSay":"en-jin-EER · noun","vocabMeaning":"Someone who plans and builds things like roads, bridges and machines, and fixes the problems along the way.","vocabExample":"In Pathbuilder you are the engineer! Plan the shortest road, build a bridge over the river, and fix your plan if it does not work.","body":"<h3>What you will learn</h3><ul><li><strong>Planning ahead.</strong> Look at the whole island before you place a card. Where are the rivers, trees and rocks? What is the shortest way home?</li><li><strong>Thinking in space.</strong> Turn a card in your head to see if its road will line up with the one next to it.</li><li><strong>How bridges help.</strong> Real engineers use bridges to carry a road over water or over another road. In Pathbuilder a bridge only goes straight, just like many real ones.</li><li><strong>Fewer is better.</strong> The par shows the shortest road. Using fewer cards means a smarter plan, and every engineer tries again to make a design better.</li></ul><p>After you play, try the Bottle-Cap Marble Run activity. Tape a track to a wall and test how steep and how curvy it can be before the marble leaves the track, just like an engineer testing a new road.</p>","textFirst":"after","aiPrompt":"","aiPromptTitle":"","aiPromptTip":"","buttonLabel":"","buttonUrl":"","email":{"on":false,"subject":"A new game for you: Pathbuilder","preview":"Build roads, cross rivers and drive the little red car home.","message":"We made a new game for our newsletter family: Pathbuilder.\n\nBuild a road one card at a time, cross rivers on bridges, and drive the little red car all the way home. Play on your own or with a friend online.","button":"Play now"},"adminNote":"Also on the public Play page. Published in the archive only. NOT emailed: email is off, send it from the Newsletter tools only if you want to.","updatedAt":"2026-10-28T06:00:00.000Z"}$j$::jsonb)
